{"code": "
def longest_path(graph, node, visited):
    """Find the longest path starting from `node` with `visited` set."""
    max_len = 1
    for neighbor in graph[node]:
        if neighbor not in visited:
            visited.add(neighbor)
            current_len = 1 + longest_path(graph, neighbor, visited)
            max_len = max(max_len, current_len)
            visited.remove(neighbor)
    return max_len

def solve():
    while True:
        n = int(input())
        if n == 0:
            break

        graph = {i: [] for i in range(1, 101)}
        for _ in range(n):
            a, b = map(int, input().split())
            graph[a].append(b)
            graph[b].append(a)

        max_chain_length = 0
        for start in range(1, 101):
            visited = set([start])
            chain_length = longest_path(graph, start, visited)
            max_chain_length = max(max_chain_length, chain_length)

        print(max_chain_length)

solve()
