def compute_grundy(m, k, memo):
    if m < k:
        return 0
    if m in memo:
        return memo[m]

    # Find all divisors of m
    divisors = set()
    for i in range(1, int(m**0.5) + 1):
        if m % i == 0:
            divisors.add(i)
            divisors.add(m // i)

    # Find valid splits
    valid_splits = set()
    for t in divisors:
        if t > 1 and m // t >= k:
            valid_splits.add(t)

    # Compute Grundy numbers for valid splits
    grundy_values = set()
    for t in valid_splits:
        grundy_values.add(compute_grundy(m // t, k, memo))

    # Find mex
    mex = 0
    while mex in grundy_values:
        mex += 1

    memo[m] = mex
    return mex

n, m, k = map(int, input().split())
memo = {}
g = compute_grundy(m, k, memo)

if n * g % 2 == 1:
    print("Timur")
else:
    print("Marsel")
"}

