n, m1, m2 = map(int, input().split())

# Find connected components for Mocha's forest
mocha_parent = list(range(n + 1))

def find_mocha(u):
    while mocha_parent[u] != u:
        mocha_parent[u] = mocha_parent[mocha_parent[u]]
        u = mocha_parent[u]
    return u

def union_mocha(u, v):
    pu = find_mocha(u)
    pv = find_mocha(v)
    if pu != pv:
        mocha_parent[pu] = pv

for _ in range(m1):
    u, v = map(int, input().split())
    union_mocha(u, v)

# Find connected components for Diana's forest
diana_parent = list(range(n + 1))

def find_diana(u):
    while diana_parent[u] != u:
        diana_parent[u] = diana_parent[diana_parent[u]]
        u = diana_parent[u]
    return u

def union_diana(u, v):
    pu = find_diana(u)
    pv = find_diana(v)
    if pu != pv:
        diana_parent[pu] = pv

for _ in range(m2):
    u, v = map(int, input().split())
    union_diana(u, v)

# Find all components in both forests
mocha_components = {}
for i in range(1, n + 1):
    if find_mocha(i) == i:
        mocha_components[i] = []
        for j in range(1, n + 1):
            if find_mocha(j) == i:
                mocha_components[i].append(j)

# Find all components in both forests
diana_components = {}
for i in range(1, n + 1):
    if find_diana(i) == i:
        diana_components[i] = []
        for j in range(1, n + 1):
            if find_diana(j) == i:
                diana_components[i].append(j)

# Find common components
common_components = set(mocha_components.keys()) & set(diana_components.keys())

# For each common component, find nodes that can connect to other components
result = []

# For each node, try to connect it to another node in a different component
for i in range(1, n + 1):
    # Find component of i in both forests
    comp_mocha = find_mocha(i)
    comp_diana = find_diana(i)

    # Try to connect to another node
    for j in range(1, n + 1):
        if i != j:
            comp_mocha_j = find_mocha(j)
            comp_diana_j = find_diana(j)

            # Check if connecting i-j would create a cycle in both forests
            if comp_mocha != comp_mocha_j and comp_diana != comp_diana_j:
                # Add this edge
                result.append((i, j))

                # Union in both forests
                union_mocha(i, j)
                union_diana(i, j)

                # Break after finding one valid edge for this node
                break

print(len(result))
for u, v in result:
    print(u, v)
