    b -= 1

    # Check if the new road creates shorter paths
    for i in range(n):
        for j in range(n):
            # Check if path through new road is shorter
            new_dist = dist[i][a] + c + dist[b][j]
            if new_dist < dist[i][j]:
                dist[i][j] = new_dist
            new_dist = dist[i][b] + c + dist[a][j]
            if new_dist < dist[i][j]:
                dist[i][j] = new_dist

    # Calculate sum of all shortest distances
    total = 0
    for i in range(n):
        for j in range(i + 1, n):
            total += dist[i][j]

    results.append(str(total))

