def solve():
    MOD = 1000000007

    # Read input
    d, n = map(int, input().split())
    a = list(map(int, input().split()))

    # Build adjacency list
    from collections import defaultdict
    adj = defaultdict(list)
    for _ in range(n - 1):
        u, v = map(int, input().split())
        adj[u - 1].append(v - 1)
        adj[v - 1].append(u - 1)

    # Tree DP
    # dp[u][s] = number of valid sets in subtree rooted at u with sum exactly s
    # We'll use a list of dictionaries

    def dfs(u, parent):
        # Base case: leaf node (no children except parent)
        if len(adj[u]) == 1 and adj[u][0] == parent:
            # Only the node itself
            dp[u] = {0: 1, a[u]: 1}
            return

        # Combine DP tables from children
        child_dps = []
        for v in adj[u]:
            if v != parent:
                dfs(v, u)
                child_dps.append(dp[v])

        # Start with the current node itself
        current_dp = {0: 1, a[u]: 1}

        # Combine with each child's DP
        for child_dp in child_dps:
            new_dp = {}
            # Combine current sets with child sets
            for s1, cnt1 in current_dp.items():
                for s2, cnt2 in child_dp.items():
                    s = s1 + s2
                    if s <= d:
                        new_dp[s] = (new_dp.get(s, 0) + cnt1 * cnt2) % MOD

            # Also consider taking just the child sets
            for s, cnt in child_dp.items():
                if s <= d:
                    new_dp[s] = (new_dp.get(s, 0) + cnt) % MOD

            current_dp = new_dp

        dp[u] = current_dp

    # Initialize DP
    dp = [{} for _ in range(n)]

    # Start DFS from node 0
    dfs(0, -1)

    # Count all valid sets in the whole tree
    result = 0
    for s, cnt in dp[0].items():
        if s <= d:
            result = (result + cnt) % MOD

    print(result)

solve()
