def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def smallest_coprime(m):
    if m == 0:
        return 0
    for i in range(1, m + 1):
        if gcd(i, m) == 1:
            return i
    return 0

def get_divisors(n):
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sorted(divisors)

def solve():
    a, b = map(int, input().split())
    d = abs(b - a)

    if d == 0:
        print(0)
        return

    divisors = get_divisors(d)

    min_lcm = float('inf')
    best_k = 0

    for g in divisors:
        m = d // g
        coprime = smallest_coprime(m)
        x = g * coprime

        # Find the smallest x >= a that is a multiple of g and x/g is coprime with m
        if x < a:
            # Find the smallest multiple of g >= a
            x = ((a + g - 1) // g) * g

        y = x + d
        lcm = x * y // gcd(x, y)

        if lcm < min_lcm or (lcm == min_lcm and x - a < best_k):
            min_lcm = lcm
            best_k = x - a

    print(best_k)

solve()
