    b_count = 0
    w_b_pairs = 0

    for c in reversed(S):
        if c == 'B':
            b_count += 1
        elif c == 'W':
            w_b_pairs += b_count

    # The maximum number of operations is the minimum of the two counts
    # because each operation involves one 'B' and one 'W'
    print(min(b_w_pairs, w_b_pairs))

