T = int(input())
for _ in range(T):
    n, k = map(int, input().split())
    oranges = []
    for _ in range(n):
        cost, weight = map(int, input().split())
        oranges.append((cost, weight))

    max_weight = 0

    # Generate all possible subsets
    for mask in range(1 << n):
        total_cost = 0
        total_weight = 0
        for i in range(n):
            if mask & (1 << i):
                total_cost += oranges[i][0]
                total_weight += oranges[i][1]

        if total_cost <= k:
            max_weight = max(max_weight, total_weight)

    print(max_weight)
