def solve():
    import sys
    input = sys.stdin.read().split()

    if not input:
        return

    N = int(input[0])
    L = int(input[1])
    A = list(map(int, input[2:2+N]))

    # Precompute p_max for all i from 1 to L
    p_max = [0] * (L + 1)  # 1-indexed

    for i in range(2, L + 1):
        # Find prime factorization of i
        max_exp = 0
        prime_with_max_exp = i  # default to i itself

        # Try dividing by all primes up to sqrt(i)
        for p in range(2, int(i**0.5) + 1):
            if i % p == 0:
                exp = 0
                temp = i
                while temp % p == 0:
                    temp //= p
                    exp += 1
                if exp > max_exp or (exp == max_exp and p < prime_with_max_exp):
                    max_exp = exp
                    prime_with_max_exp = p

        # If i is still > 1, it's a prime factor
        if i > 1:
            exp = 1
            if exp > max_exp or (exp == max_exp and i < prime_with_max_exp):
                max_exp = exp
                prime_with_max_exp = i

        p_max[i] = prime_with_max_exp

    # Perform operations
    for i in range(1, L + 1):
        if i == 1 or p_max[i] % i % 2 == 1:
            # Beneficial: double the largest element
            if A:
                max_val = max(A)
                idx = A.index(max_val)
                A[idx] *= 2
        else:
            # Harmful: divide the smallest element
            if A:
                min_val = min(A)
                idx = A.index(min_val)
                A[idx] //= 2
                # Remove element if it became 0
                if A[idx] == 0:
                    A.pop(idx)

    # Output
    print(len(A))
    if A:
        print(' '.join(map(str, sorted(A))))
    else:
        print()

solve()
