def on_segment(p, q, r):
    """Check if point q lies on segment pr"""
    # Check if q is between p and r
    if min(p[0], r[0]) <= q[0] <= max(p[0], r[0]) and min(p[1], r[1]) <= q[1] <= max(p[1], r[1]):
        # Check if the cross product is zero (collinear)
        cross = (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])
        return cross == 0
    return False

def dot_product(a, b):
    """Calculate dot product of vectors a and b"""
    return a[0] * b[0] + a[1] * b[1]

def angle_between(v1, v2):
    """Calculate angle between vectors v1 and v2 in degrees"""
    dot = dot_product(v1, v2)
    mag1 = (v1[0]**2 + v1[1]**2)**0.5
    mag2 = (v2[0]**2 + v2[1]**2)**0.5
    cos_theta = dot / (mag1 * mag2)
    # Handle floating point precision issues
    cos_theta = max(min(cos_theta, 1.0), -1.0)
    return math.degrees(math.acos(cos_theta))

def solve():
    t = int(input())
    for _ in range(t):
        segments = []
        for _ in range(3):
            x1, y1, x2, y2 = map(int, input().split())
            segments.append(((x1, y1), (x2, y2)))

        found = False
        # Try all permutations of which segment is first, second, third
        for first_idx in range(3):
            for second_idx in range(3):
                if first_idx == second_idx:
                    continue
                third_idx = 3 - first_idx - second_idx

                # Get segments
                first = segments[first_idx]
                second = segments[second_idx]
                third = segments[third_idx]

                # Check if first and second share a common endpoint
                common = False
                for p in first:
                    for q in second:
                        if p == q:
                            common = True
                            break
                    if common:
                        break
                if not common:
                    continue

                # Find the common endpoint
                common_point = None
                for p in first:
                    for q in second:
                        if p == q:
                            common_point = p
                            break
                    if common_point:
                        break

                # Check if third connects points on first and second
                # Find points on first and second
                p1 = None
                p2 = None
                for pt in third:
                    if on_segment(first[0], first[1], pt):
                        p1 = pt
                    elif on_segment(second[0], second[1], pt):
                        p2 = pt

                if p1 is None or p2 is None:
                    continue

                # Check angle condition
                # Vectors from common point
                v1 = (p1[0] - common_point[0], p1[1] - common_point[1])
