def max_overlap(a, b):
    """Calculate maximum overlap where suffix of a matches prefix of b"""
    max_overlap = 0
    for i in range(1, min(len(a), len(b)) + 1):
        if a[-i:] == b[:i]:
            max_overlap = i
    return max_overlap

def solve():
    import sys
    input = sys.stdin.read().splitlines()
    idx = 0

    while True:
        if idx >= len(input):
            break

        n = int(input[idx].strip())
        idx += 1

        if n == 0:
            break

        cities = []
        for _ in range(n):
            cities.append(input[idx].strip())
            idx += 1

        # Calculate overlaps between all pairs
        overlaps = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    overlaps[i][j] = max_overlap(cities[i], cities[j])

        # DP with bitmasking
        INF = float('inf')
        dp = [[INF] * n for _ in range(1 << n)]

        # Initialize: only one city
        for i in range(n):
            dp[1 << i][i] = len(cities[i])

        # Fill DP table
        for mask in range(1, 1 << n):
            for last in range(n):
                if not (mask & (1 << last)):
                    continue

                if dp[mask][last] == INF:
                    continue

                # Try adding each other city
                for next_city in range(n):
                    if mask & (1 << next_city):
                        continue

                    # Calculate new length
                    new_len = dp[mask][last] + len(cities[next_city]) - overlaps[last][next_city]

                    # Update DP
                    if new_len < dp[mask | (1 << next_city)][next_city]:
                        dp[mask | (1 << next_city)][next_city] = new_len

        # Find minimum length
        min_len = min(dp[(1 << n) - 1][i] for i in range(n))
        print(min_len)

solve()
