def min_time(n, x, y, memo={}):
    if n == 0:
        return 0
    if n == 1:
        return min(x, y)

    if n in memo:
        return memo[n]

    # Option 1: Insert one 'a'
    option1 = x + min_time(n - 1, x, y, memo)

    # Option 2: Copy (requires at least 1 'a')
    option2 = y + min_time(n // 2, x, y, memo)

    memo[n] = min(option1, option2)
    return memo[n]

n, x, y = map(int, input().split())
