t = int(input())
for _ in range(t):
    a, b, c, m = map(int, input().split())
    total = a + b + c

    if m == 0:
        # Check if we can alternate letters
        # Maximum frequency should be <= (total + 1) // 2
        if max(a, b, c) <= (total + 1) // 2:
            print("YES")
        else:
            print("NO")
    else:
        # Check if we can create m adjacent equal pairs
        # We need at least one letter that appears at least twice
        if max(a, b, c) >= 2:
            # Maximum possible adjacent equal pairs
            max_pairs = min(total - 1, a + b + c - 3)
            if m <= max_pairs:
                print("YES")
            else:
                print("NO")
        else:
            print("NO")
"}

