import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Calculate sum of d(ai, aj) for all pairs (i, j) with 1 <= i <= j <= n
    # d(ai, aj) = (ai & aj) - (ai | aj) if i < j, and 0 if i == j

    total = 0
    for i in range(n):
        for j in range(i, n):
            if i == j:
