    digits = set(str(x))
    return len(digits) <= k

def solve():
    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())

        # Try all numbers made of the same digit for k=1
        if k == 1:
            for d in range(1, 10):
                # Create a number with all digits d
                num_str = str(d) * len(str(n))
                num = int(num_str)
                if num >= n:
                    print(num)
                    break
            continue

        # For k=2, try all combinations of two digits
        # Try all pairs of digits (including the same digit twice)
        for d1 in range(10):
            for d2 in range(d1, 10):
                # Try all numbers made with these two digits
                # Start from the number with all digits d1
                num_str = str(d1) * len(str(n))
                num = int(num_str)

                # Try increasing the number by replacing digits
                while True:
                    if is_k_beautiful(num, k):
                        print(num)
                        break

                    # Try to increment the number
                    # Find the rightmost digit that can be increased
                    digits = list(str(num))
                    found = False
                    for i in range(len(digits) - 1, -1, -1):
                        if digits[i] < '9':
                            digits[i] = str(int(digits[i]) + 1)
                            found = True
                            break
                    if not found:
                        # All digits are 9, we need to add a digit
                        digits = ['1'] + digits
                    num = int(''.join(digits))

solve()
